请对以下 case 进行三维加权评分。

=== case_id ===
Case-08-sleep-006

=== 用户原始指令 (query.txt) ===
深睡时长数字会变，能读一下天气情况吧，要看到红色危险提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "深睡时长数字会变，能读一下天气情况吧，要看到红色危险提示",
  "size": "2x4",
  "eventCandidates": [],
  "dataModelSchema": {
    "data": {
      "sleep": {
        "deepSleepMinutes": {
          "type": "number",
          "description": "深睡时长分钟数，用于驱动主进度环动态变化。",
          "sampleValue": 102
        },
        "deepSleepTargetMinutes": {
          "type": "number",
          "description": "深睡目标分钟数，用于计算深睡时长进度。",
          "sampleValue": 120
        },
        "deepSleepText": {
          "type": "string",
          "description": "深睡时长的短文本展示。",
          "sampleValue": "1h42m"
        },
        "statusText": {
          "type": "string",
          "description": "睡眠状态短提示。",
          "sampleValue": "危险"
        },
        "riskAlertText": {
          "type": "string",
          "description": "需要以危险提示展示的睡眠风险文案。",
          "sampleValue": "危险：深睡偏低，注意恢复"
        }
      },
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询地区名称。",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "小雨"
          },
          "airQuality": {
            "type": "string",
            "description": "当前空气质量等级。",
            "sampleValue": "良"
          },
          "humidityPercent": {
            "type": "number",
            "description": "当前相对湿度百分比。",
            "sampleValue": 78
          },
          "windLevel": {
            "type": "integer",
            "description": "当前风力等级。",
            "sampleValue": 3
          },
          "alertLevel": {
            "type": "string",
            "description": "当前天气预警信息。",
            "sampleValue": "无预警"
          }
        }
      }
    }
  },
  "assetCandidates": []
}

